INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','flashcard','What is the onset of action of a SABA (e.g., albuterol) when inhaled?','["5-30 minutes (bronchodilation for 4-6 hours)"]','A','SABAs are the first-line rescue medications for acute bronchospasm. All asthmatic patients should have a SABA inhaler available. Use with a spacer improves delivery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','flashcard','Name two short-acting beta-2 agonists (SABAs) used in asthma.','["Albuterol (salbutamol) and levalbuterol (levo-salbutamol)"]','A','Levalbuterol is the R-enantiomer of albuterol and is thought to cause fewer cardiovascular side effects. Both provide 4-6 hours of bronchodilation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','flashcard','Name two long-acting beta-2 agonists (LABAs) used in asthma and COPD.','["Salmeterol and formoterol (provide more than 12 hours of bronchodilation)"]','A','LABAs must NEVER be used as monotherapy in asthma — always combine with ICS. Formoterol has a faster onset than salmeterol and can be used for acute symptom relief in ICS/formoterol combinations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','flashcard','Why must LABAs never be used as monotherapy in asthma?','["LABA monotherapy is associated with increased risk of asthma-related death; LABAs lack anti-inflammatory effects and must be combined with ICS"]','A','Post-marketing data revealed severe asthma-related events and death with LABA monotherapy. LABAs are adjunctive therapy to ICS, never sole controllers in asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','flashcard','What electrolyte abnormality can occur with high-dose or nebulised beta-2 agonist therapy and why?','["Hypokalemia \u2014 beta-2 receptor stimulation activates Na+/K+-ATPase on skeletal muscle, driving K+ intracellularly"]','A','Also watch for hyperglycemia, hypomagnesemia, and tachycardia with high doses. Monitor electrolytes during high-dose nebulisation in acute severe asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','flashcard','Which beta-2 agonists are approved for once-daily dosing in COPD?','["Indacaterol, olodaterol, and vilanterol (ultra-LABAs)"]','A','LABAs are first-line maintenance bronchodilators in COPD. Once-daily dosing improves adherence. These ultra-LABAs are not used in asthma as monotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','flashcard','What is the pharmacological selectivity difference between albuterol and isoprenaline (isoproterenol)?','["Albuterol is beta-2 selective (minimal beta-1 effects); isoprenaline is non-selective (stimulates beta-1 and beta-2 equally), causing more tachycardia and cardiovascular effects"]','A','Beta-2 selectivity of albuterol means it causes less tachycardia and hypertension than non-selective agents. However, at high doses, some beta-1 stimulation still occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','flashcard','What is the clinical significance of formoterol''''s faster onset compared to salmeterol?','["Formoterol has a faster onset (~3-5 minutes) allowing ICS/formoterol combinations to be used for both maintenance AND as-needed relief (SMART therapy) in moderate persistent asthma"]','A','SMART (Single Maintenance and Reliever Therapy) with budesonide/formoterol reduces exacerbations compared to fixed-dose regimens. Salmeterol cannot be used for rescue therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','hard','flashcard','What is the mechanism by which beta-2 agonists cause bronchodilation at the cellular level?','["Beta-2 agonists bind Gs-coupled beta-2 receptors \u2192 activate adenylyl cyclase \u2192 increase cAMP \u2192 activate PKA \u2192 phosphorylate myosin light chain kinase (inhibiting it) and activate K+ channels \u2192 smooth muscle relaxation"]','A','Increased cAMP also reduces intracellular calcium, contributing to smooth muscle relaxation. This is distinct from the anti-inflammatory mechanism of ICS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','hard','flashcard','What is the risk of beta-2 agonist tolerance (tachyphylaxis) with chronic SABA overuse, and how does it manifest clinically?','["Chronic overuse of SABAs can lead to receptor downregulation (tachyphylaxis), reducing bronchodilatory response; frequent SABA use (>2 days/week) is a marker of poorly controlled asthma requiring step-up therapy"]','A','SABA overuse is associated with increased asthma mortality. The mainstay of treatment should be anti-inflammatory therapy (ICS), with SABA reserved for rescue. Overuse is an indicator to add or increase ICS.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','flashcard','What is the mechanism of bronchodilation by inhaled anticholinergics?','["Blockade of M3 muscarinic receptors on airway smooth muscle and mucus glands, reducing vagally mediated bronchoconstriction and mucus secretion"]','A','Acetylcholine normally causes bronchoconstriction via M3 receptors. Anticholinergics are particularly effective in COPD where vagal tone is high.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','flashcard','Classify ipratropium and tiotropium by duration of action.','["Ipratropium = SAMA (Short-Acting Muscarinic Antagonist), dosed 3-4x daily; Tiotropium = LAMA (Long-Acting Muscarinic Antagonist), dosed once daily"]','A','Other LAMAs include aclidinium (twice daily), glycopyrrolate/umeclidinium (once daily). LAMAs are preferred for maintenance in stable COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','flashcard','Which structural feature of ipratropium and tiotropium minimises systemic anticholinergic side effects?','["Both are quaternary ammonium compounds \u2014 charged molecules that are poorly absorbed from the GI tract, minimising systemic effects"]','A','Because they are charged, they do not cross the blood-brain barrier and have minimal oral absorption. However, small amounts absorbed via the lungs can still cause local effects such as dry mouth and urinary retention in BPH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','flashcard','What is the preferred role of ipratropium in asthma management?','["Ipratropium is NOT first-line in asthma (onset too slow compared to SABAs); it is used as add-on to SABA in acute severe asthma in the emergency department, or in patients who cannot tolerate SABAs"]','A','In COPD, ipratropium has a more central role as a short-acting bronchodilator. In asthma-COPD overlap, both SABA and SAMA may be combined.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','flashcard','What local adverse effects are associated with inhaled anticholinergic bronchodilators?','["Dry mouth (xerostomia) and bitter taste \u2014 most common; also nasal dryness, urinary retention (in BPH), blurred vision (if drug contacts eyes)"]','A','These are due to anticholinergic blockade of muscarinic receptors at local mucosal sites. Systemic anticholinergic effects are uncommon due to the quaternary ammonium structure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','flashcard','In COPD management, when is combination LABA + LAMA therapy preferred over monotherapy?','["When a single long-acting bronchodilator provides inadequate symptom control or when the patient is at risk of exacerbations despite monotherapy"]','A','Combining LABA and LAMA provides additive bronchodilation via different mechanisms (beta-2 stimulation vs. muscarinic blockade). Available as fixed-dose combinations (e.g., tiotropium/olodaterol).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','flashcard','Name four long-acting muscarinic antagonists (LAMAs) used in COPD.','["Tiotropium, aclidinium, glycopyrrolate (glycopyrronium), umeclidinium"]','A','All LAMAs block M1, M2, M3 muscarinic receptors with prolonged M3 dissociation. Tiotropium is the most widely studied. Umeclidinium is available in once-daily fixed combination with vilanterol (LABA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','flashcard','A patient with COPD and BPH is prescribed tiotropium. What specific precaution is required?','["Warn the patient about the risk of acute urinary retention; monitor for symptoms of urinary difficulty; consider avoiding in severe BPH or advise urological review first"]','A','Although systemic absorption of inhaled tiotropium is low, even small amounts absorbed via the lungs can worsen bladder outlet obstruction in men with BPH by reducing detrusor muscle contraction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','hard','flashcard','Why does tiotropium provide 24-hour bronchodilation despite also blocking M2 receptors, which could paradoxically increase ACh release?','["Tiotropium dissociates very slowly from M3 receptors (prolonged M3 blockade) but dissociates more rapidly from M2 receptors, partially restoring M2 inhibitory feedback on ACh release \u2014 this kinetic selectivity for M3 allows once-daily efficacy"]','A','This kinetic selectivity (kinetic not affinity) for M3 over M2 means tiotropium achieves prolonged bronchodilation without excessively disinhibiting acetylcholine release. This is the basis of its once-daily dosing efficacy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','hard','flashcard','What is the pharmacological rationale for combining ipratropium with salbutamol in a single nebuliser in acute asthma exacerbations in hospital?','["Ipratropium and salbutamol act via different mechanisms (muscarinic blockade vs. beta-2 stimulation) and produce additive bronchodilation; the combination reduces hospitalisation duration compared to SABA alone in acute severe asthma"]','A','Ghana STG 2017 recommends this combination in acute moderate/severe asthma exacerbations in hospital. The combination is particularly useful in severe exacerbations not responding adequately to SABA alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','flashcard','Name three inhaled corticosteroids (ICS) used in asthma management.','["Beclomethasone (beclometasone), budesonide, fluticasone \u2014 also ciclesonide and mometasone"]','A','ICS are the drugs of choice for long-term control in persistent asthma. They must be used regularly (not PRN) for anti-inflammatory benefit. Ghana STG 2017 lists fluticasone, beclomethasone, and budesonide/formoterol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','flashcard','What is the most common local adverse effect of inhaled corticosteroids and how is it prevented?','["Oropharyngeal candidiasis (oral thrush) \u2014 prevented by rinsing the mouth with water (swish-and-spit) after each ICS use and using a spacer device"]','A','ICS deposit in the oral cavity and suppress local immunity, allowing Candida overgrowth. Hoarseness (dysphonia) is another local side effect. If candidiasis occurs, treat with topical antifungals (nystatin, clotrimazole).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','flashcard','How do ICS reduce airway inflammation in asthma?','["ICS inhibit phospholipase A2, reducing arachidonic acid release and downstream prostaglandin and leukotriene production; also decrease eosinophils, macrophages, and T lymphocytes; reverse mucosal edema and reduce capillary permeability"]','A','ICS reduce airway hyperresponsiveness with regular use. They do not provide immediate bronchodilation. Full anti-inflammatory benefit takes several weeks of regular use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','flashcard','What percentage of ICS dose reaches the lungs with an MDI (without spacer), and where does the rest go?','["Only 10-20% reaches the airways; 80-90% is deposited in the oropharynx, swallowed, and partly absorbed from the GI tract contributing to systemic exposure"]','A','Adding a spacer significantly increases lung delivery and reduces oropharyngeal deposition. Systemic absorption occurs from both the GI tract and the lungs, which is how systemic side effects occur with high-dose ICS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','flashcard','Why are ICS preferred over oral corticosteroids for long-term asthma control?','["ICS deliver drug directly to the airway site of action with minimal systemic absorption at standard doses, avoiding the serious systemic adverse effects of long-term oral corticosteroids (osteoporosis, HPA suppression, hyperglycemia, growth retardation)"]','A','Oral corticosteroids are reserved for acute severe exacerbations or refractory asthma. Long-term oral steroids carry risks of Cushing''''s syndrome, adrenal suppression, osteoporosis, and growth retardation in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','flashcard','What is the technique difference between using a metered-dose inhaler (MDI) and a dry powder inhaler (DPI)?','["MDI: Exhale, then inhale SLOWLY and DEEPLY while pressing canister (spacer helps). DPI: Inhale QUICKLY and DEEPLY (no spacer used). Both: Rinse mouth after ICS use."]','A','The DPI requires fast, forceful inhalation to de-aggregate the powder for optimal lung deposition. MDI benefits from a spacer to reduce particle velocity. This difference in technique is a common source of patient error.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','flashcard','When are ICS recommended in COPD (as opposed to asthma, where they are first-line)?','["In COPD, ICS are added to long-acting bronchodilators only in patients with FEV1 <60% predicted OR patients with features of both asthma and COPD (overlap syndrome); NOT for all COPD patients due to increased pneumonia risk"]','A','In asthma, ICS are first-line for all persistent disease. In COPD, they carry additional pneumonia risk without benefit in mild disease. This is a key distinction between asthma and COPD management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','flashcard','What systemic adverse effects can occur with high-dose or long-term ICS use?','["HPA axis suppression, reduced bone mineral density (osteoporosis), growth retardation in children, skin thinning/bruising, cataracts \u2014 all dose-dependent and more common with high-dose ICS"]','A','Standard doses of ICS in adults have minimal systemic effects. These effects are more relevant with high doses, in children, and in elderly patients. Using the lowest effective dose minimises risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','hard','flashcard','Ciclesonide is a prodrug ICS. How does this property confer clinical advantages?','["Ciclesonide is activated by esterases in the lung to its active form (des-ciclesonide); this pulmonary-selective activation reduces systemic bioavailability and oropharyngeal deposition, resulting in fewer local side effects including candidiasis and dysphonia"]','A','Beclomethasone is also a prodrug. Pulmonary activation means drug is only active where it is needed. However, clinical superiority over other ICS has not been definitively established in randomised trials.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','hard','flashcard','A patient on chronic high-dose ICS undergoes major surgery and develops postoperative hypotension refractory to fluids. What HPA axis-related mechanism explains this, and what is the management?','["Chronic high-dose ICS can suppress the HPA axis via systemic absorption; under surgical stress, suppressed adrenal glands cannot produce adequate cortisol causing adrenal crisis; management is intravenous hydrocortisone (stress-dose corticosteroid cover)"]','A','Patients on long-term high-dose ICS should be identified preoperatively and given perioperative corticosteroid cover (e.g., hydrocortisone 100 mg IV at induction, then 8-hourly for 24-48 hours). This is analogous to management of patients on oral steroids.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','flashcard','What is the mechanism of action of theophylline?','["Inhibition of phosphodiesterase (PDE) increasing cAMP causing bronchodilation; plus adenosine receptor antagonism; possible anti-inflammatory effects via HDAC2 activation at low doses"]','A','Theophylline was previously the mainstay of asthma therapy but has been largely replaced by safer, more effective drugs. It still has a role in low-resource settings and selected COPD patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','flashcard','What is the therapeutic serum concentration range for theophylline, and what happens above and below this range?','["Therapeutic range: 10-20 mcg/mL. Below 10: sub-therapeutic (poor bronchodilation). Above 20: toxicity \u2014 nausea, arrhythmias, seizures"]','A','Theophylline has one of the narrowest therapeutic windows in clinical pharmacology. Regular monitoring of serum levels is essential, especially when co-medications change.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','flashcard','Which drug interaction involving theophylline is most commonly tested clinically?','["Theophylline + macrolides (erythromycin, clarithromycin) or fluoroquinolones (ciprofloxacin) \u2014 these CYP1A2/3A4 inhibitors reduce theophylline metabolism, raising serum levels to toxic range"]','A','Always reduce theophylline dose and monitor levels when starting a macrolide or fluoroquinolone. The combination of theophylline + ciprofloxacin is particularly dangerous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','flashcard','How does cigarette smoking affect theophylline dosing requirements?','["Smoking induces CYP1A2, increasing theophylline metabolism and requiring higher doses; upon smoking cessation, CYP1A2 induction decreases, reducing theophylline clearance \u2014 dose must be reduced to avoid toxicity"]','A','This is a clinically important interaction. Smokers may need theophylline doses 50-100% higher than non-smokers. Quitting smoking without reducing theophylline dose can cause toxicity within days to weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','flashcard','List the signs and symptoms of theophylline toxicity, from mild to life-threatening.','["Mild: nausea, vomiting, diarrhoea, headache, irritability. Moderate: tremors, tachycardia, insomnia. Severe/life-threatening: seizures, ventricular arrhythmias (ventricular tachycardia/fibrillation)"]','A','Theophylline toxicity can occur with serum levels >20 mcg/mL. Symptoms can occur rapidly, especially with sudden changes in clearance from drug interactions. Activated charcoal may be used in acute overdose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','flashcard','Which CYP enzymes metabolise theophylline, and name drugs that are CYP inducers vs. inhibitors relevant to theophylline?','["Theophylline is metabolised by CYP1A2 and CYP3A4. Inhibitors (raise theophylline levels): macrolides, fluoroquinolones, zileuton, cimetidine. Inducers (lower levels): rifampicin, phenytoin, carbamazepine, phenobarbitone, cigarette smoking"]','A','The clinical rule: if a CYP1A2 or 3A4 inhibitor is started, reduce theophylline dose and monitor levels. If an inducer is added, theophylline dose may need to be increased to maintain therapeutic levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','flashcard','What is roflumilast, and how does it differ from theophylline in mechanism?','["Roflumilast is an oral selective phosphodiesterase-4 (PDE4) inhibitor used to reduce exacerbations in severe COPD with chronic bronchitis. Unlike theophylline (non-selective PDE inhibitor), roflumilast selectively inhibits PDE4 in lung cells, theoretically reducing systemic side effects"]','A','Roflumilast is not a bronchodilator. It is used alongside long-acting bronchodilators in COPD, not asthma. Its main side effects are GI (nausea, diarrhoea, weight loss).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','flashcard','A child with asthma is being considered for add-on theophylline therapy. What monitoring is required during use?','["Baseline and periodic serum theophylline levels; monitor for signs of toxicity (nausea, arrhythmias, seizures); liver function tests; assess for drug interactions; target serum levels 10-15 mcg/mL in children (slightly lower than in adults)"]','A','Children metabolise theophylline more rapidly than adults. Clearance varies with age, illness, and concurrent medications. Strict monitoring is essential to maintain the narrow therapeutic window.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','hard','flashcard','Why does theophylline cause tachycardia and arrhythmias in overdose?','["Theophylline inhibits cardiac PDE (increasing cAMP in cardiac cells), causing increased heart rate and contractility; at toxic levels, excessive cAMP drives ventricular ectopy and arrhythmias. Adenosine receptor antagonism in the heart also contributes by blocking the cardioprotective effects of adenosine."]','A','At therapeutic doses, cardiac effects are usually mild. At toxic levels (>20-25 mcg/mL), ventricular tachycardia and fibrillation can occur. This is the most dangerous complication of theophylline overdose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','hard','flashcard','What is the mechanism behind the anti-inflammatory properties of theophylline at lower serum concentrations (5-10 mcg/mL)?','["At sub-bronchodilatory concentrations, theophylline activates histone deacetylase-2 (HDAC2) in inflammatory cells, reversing corticosteroid resistance and reducing inflammatory gene transcription \u2014 separate from PDE inhibition"]','A','This HDAC2 mechanism may explain why low-dose theophylline can partially restore steroid sensitivity in patients with corticosteroid-resistant asthma or COPD. This property is an active area of research and may benefit smokers with COPD who have reduced HDAC2 activity.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','flashcard','Name the three main leukotriene modifiers and classify them.','["Montelukast (CysLT1 receptor antagonist); Zafirlukast (CysLT1 receptor antagonist); Zileuton (5-lipoxygenase inhibitor)"]','A','Montelukast is the most commonly used LTRA, given once daily (evening) and approved for ages 1+. Zafirlukast requires twice-daily dosing. Zileuton requires regular liver monitoring and inhibits CYP1A2.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','flashcard','What are the key effects of cysteinyl leukotrienes (LTC4, LTD4, LTE4) on the airways?','["Bronchoconstriction, increased endothelial permeability (mucosal edema), mucus hypersecretion, eosinophil recruitment \u2014 together contributing to airway obstruction in asthma"]','A','These effects make cysteinyl leukotrienes important mediators in asthma and aspirin-exacerbated respiratory disease (AERD). Blocking these effects with LTRAs provides anti-inflammatory and mild bronchodilatory benefit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','flashcard','Can montelukast be used to treat an acute asthma attack? Explain.','["No \u2014 montelukast is not a bronchodilator and has no role in acute asthma attacks; it is used for PREVENTION of asthma symptoms and should not be used when immediate bronchodilation is required"]','A','SABAs are the first-line rescue therapy for acute asthma. Montelukast takes days to weeks for full effect. It is an add-on therapy to ICS, not a rescue medication.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','flashcard','What monitoring is required for patients on zileuton?','["Liver function tests \u2014 zileuton can cause hepatotoxicity. Monitor LFTs before starting and periodically during use; discontinue if ALT/AST >3-5 times the upper limit of normal"]','A','Zileuton also inhibits CYP1A2, meaning it can increase theophylline levels if co-prescribed. This dual concern (hepatotoxicity + drug interaction with theophylline) limits zileuton''''s use compared to montelukast.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','flashcard','Why are leukotriene modifiers particularly effective in aspirin-exacerbated respiratory disease (AERD)?','["In AERD, COX inhibition by NSAIDs diverts arachidonic acid to the 5-LO pathway, causing massive leukotriene release. LTRAs block the receptor for these leukotrienes, reducing NSAID-triggered bronchoconstriction"]','A','AERD (Samter''''s triad = asthma + nasal polyps + aspirin sensitivity) affects ~10% of asthmatics. Zileuton (blocking leukotriene synthesis entirely) can also be effective. These patients should always carry a SABA for breakthrough attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','flashcard','Describe the hepatic metabolism and excretion routes of montelukast vs. zafirlukast.','["Both are highly protein-bound and extensively hepatically metabolised. Montelukast and zafirlukast undergo biliary/faecal excretion. Zileuton and its metabolites are primarily excreted in urine."]','A','The hepatic metabolism of all three means that liver disease can affect their clearance. Both zafirlukast and zileuton have clinically relevant CYP inhibitory effects (zafirlukast: CYP2C9/3A4; zileuton: CYP1A2).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','flashcard','Montelukast has been linked to neuropsychiatric side effects. Describe these and the regulatory response.','["Agitation, aggression, depression, sleep disturbances, and suicidal ideation (rare); FDA issued a black box warning in 2020, restricting use in mild allergic rhinitis where safer alternatives exist"]','A','The exact mechanism is unclear but may relate to leukotriene receptors in the brain. Clinicians should discuss these risks with patients and carers, and discontinue montelukast if neuropsychiatric symptoms develop.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','flashcard','What is the drug interaction between zafirlukast and warfarin?','["Zafirlukast inhibits CYP2C9, reducing warfarin (S-warfarin) metabolism, increasing anticoagulation effect and bleeding risk (elevated INR); INR should be monitored closely when starting or stopping zafirlukast"]','A','Other zafirlukast interactions include inhibition of CYP3A4. Food reduces zafirlukast absorption by 40%, so it should be taken on an empty stomach (1 hour before or 2 hours after meals).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','hard','flashcard','How does the mechanism of zileuton differ from that of montelukast at the arachidonic acid cascade?','["Zileuton inhibits 5-lipoxygenase (5-LO) \u2014 the first enzyme in the leukotriene synthetic pathway \u2014 blocking formation of ALL leukotrienes (LTB4 AND all cysteinyl leukotrienes). Montelukast only blocks CysLT1 receptors downstream, leaving LTB4 effects and synthesis unblocked."]','A','Because zileuton blocks leukotriene synthesis entirely (including LTB4 which attracts neutrophils and eosinophils), it may have broader anti-inflammatory effects than receptor antagonists. However, hepatotoxicity and CYP1A2 inhibition limit its use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','hard','flashcard','Describe the pharmacokinetics that make montelukast suitable for once-daily evening dosing.','["Montelukast is rapidly absorbed orally (Tmax ~3-4 hours), undergoes extensive hepatic metabolism (CYP2C8, 3A4), and has biliary/faecal excretion. Evening dosing targets peak leukotriene production during nighttime hours when asthma symptoms are typically worst."]','A','Leukotriene production exhibits a circadian rhythm peaking in the early morning (when asthma attacks are most common). Evening dosing of montelukast leverages this pattern. Montelukast''''s half-life of ~5 hours allows once-daily dosing.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','flashcard','What is the mechanism of action of cromolyn sodium (sodium cromoglicate)?','["Inhibition of mast cell degranulation \u2014 prevents release of histamine, leukotrienes, and other inflammatory mediators upon allergen exposure. Acts prophylactically, not acutely."]','A','Cromolyn is available as a nebulised solution for asthma and intranasal spray for allergic rhinitis. Due to its prophylactic mechanism, it must be used regularly before allergen exposure, not for acute attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','flashcard','What is the target of omalizumab and what disease is it used for?','["Omalizumab binds to free IgE (at the Cepsilon3 domain), preventing IgE from binding to mast cell receptors; used for moderate-to-severe persistent allergic (IgE-mediated) asthma not controlled by ICS"]','A','Omalizumab is given subcutaneously every 2-4 weeks. Patients must have confirmed IgE-mediated disease and serum IgE within an approved range (30-1500 IU/mL). Dose and interval are determined by IgE level and body weight.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','flashcard','Name three IL-5-targeting monoclonal antibodies used in eosinophilic asthma.','["Mepolizumab (binds IL-5 directly), reslizumab (binds IL-5 directly), benralizumab (binds IL-5 receptor alpha, triggering eosinophil depletion via ADCC)"]','A','These biologics are for severe eosinophilic asthma not controlled by ICS. They require confirmed eosinophilic phenotype (blood eosinophils typically >300/mcL). Mepolizumab and benralizumab are subcutaneous; reslizumab is intravenous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','flashcard','What are the limitations of cromolyn sodium that restrict its widespread use in asthma?','["Requires 3-4 times daily dosing (poor adherence); not a bronchodilator (no benefit for acute attacks); inferior to ICS for long-term control; only available as nebulised solution; frequent minor side effects (cough, irritation, unpleasant taste)"]','A','Cromolyn was widely used before ICS became available. Its use is now limited mainly to situations where ICS are not tolerable or in very mild disease. Intranasal cromolyn is more commonly used for allergic rhinitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','flashcard','How does omalizumab reduce mast cell activation without causing degranulation itself?','["Omalizumab binds to free (circulating) IgE at the same Cepsilon3 site that binds FcepsilonRI on mast cells, forming IgE-omalizumab complexes that cannot bind the receptor. It does NOT bind IgE already on mast cells, so no cross-linking and no degranulation occurs."]','A','Over time, surface FcepsilonRI expression on mast cells decreases due to reduced receptor occupancy, further reducing allergic responsiveness. The net effect is a markedly reduced allergic response to allergen exposure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','flashcard','Which safety precaution is mandatory after each omalizumab injection?','["Patients must be observed for at least 30-60 minutes after each injection due to the risk of anaphylaxis (typically occurring within 2 hours); patients should carry a self-injectable epinephrine (adrenaline) pen after discharge"]','A','Anaphylaxis with omalizumab is rare but serious. Most cases occur with the first few injections. The risk does not disappear completely over time, so ongoing observation is required at every clinic visit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','flashcard','Dupilumab is a newer biologic for asthma. What is its target and mechanism?','["Dupilumab targets the IL-4 receptor alpha subunit (IL-4Ralpha), blocking both IL-4 and IL-13 signalling, which drive type 2 inflammation in asthma and atopic dermatitis"]','A','Dupilumab is also approved for atopic dermatitis and chronic rhinosinusitis with nasal polyps, making it useful in patients with multiple type 2 inflammatory conditions. It reduces eosinophilic inflammation and IgE production.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','flashcard','What determines the dose and frequency of omalizumab?','["Dose and dosing interval (every 2 or 4 weeks) are determined by the patient''''s baseline total serum IgE level and body weight, using a dosing table provided by the manufacturer"]','A','Omalizumab cannot be given if IgE is too high (>1500 IU/mL) or too low (<30 IU/mL) — it is calibrated to form IgE-antibody complexes in the appropriate range. Dose calculation from the table is essential before prescribing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','hard','flashcard','Explain how benralizumab causes near-complete eosinophil depletion more rapidly than mepolizumab.','["Benralizumab binds to the IL-5 receptor alpha subunit (IL-5Ralpha) on eosinophils and basophils, then triggers antibody-dependent cell-mediated cytotoxicity (ADCC) via NK cells, causing rapid eosinophil lysis. This is faster and more complete than mepolizumab, which merely blocks IL-5 from binding its receptor without direct eosinophil killing."]','A','Benralizumab achieves near-complete depletion of blood and tissue eosinophils within weeks. Mepolizumab reduces (but does not deplete) eosinophil counts. Benralizumab''''s mechanism allows for 8-weekly dosing after initial monthly doses (after first 3 doses).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','hard','flashcard','Tezepelumab is the newest biologic approved for severe uncontrolled asthma. What is its upstream target and why is it described as phenotype-agnostic?','["Tezepelumab targets thymic stromal lymphopoietin (TSLP) \u2014 an epithelial-derived alarmin released in response to allergens, pollutants, and infection. TSLP activates multiple inflammatory pathways (type 2 and non-type 2), so blocking it upstream reduces inflammation regardless of phenotype"]','A','Unlike biologics targeting specific downstream mediators (IL-5, IL-4, IgE), tezepelumab''''s upstream target means it can benefit asthma patients regardless of eosinophilic phenotype. This is clinically important as not all severe asthma is type 2 eosinophilic.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','flashcard','What is the mucolytic mechanism of N-acetylcysteine (NAC)?','["NAC''''s free sulfhydryl (SH) group breaks disulfide bonds in mucus glycoproteins, reducing the cross-linking of the mucus gel and decreasing mucus viscosity"]','A','NAC can be given orally, intravenously (for paracetamol overdose), or by nebulisation. Nebulised NAC can cause bronchospasm — a SABA pre-treatment is recommended in susceptible patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','flashcard','Name two clinical uses of N-acetylcysteine outside of mucolytic therapy.','["1. Antidote for paracetamol (acetaminophen) overdose \u2014 replenishes hepatic glutathione. 2. Potentially nephroprotective in contrast-induced nephropathy (though evidence is mixed)."]','A','For paracetamol overdose, NAC is given IV as a 21-hour protocol (if within 8-10 hours of overdose) or oral as a 72-hour protocol (if later). The free SH group enables both mucolysis and glutathione replenishment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','flashcard','What is the difference between a mucolytic and an expectorant?','["Mucolytics (e.g., NAC, carbocisteine) chemically break down mucus structure reducing viscosity. Expectorants (e.g., guaifenesin) increase respiratory secretion volume and water content making mucus easier to clear by coughing and ciliary action."]','A','Both approaches aid mucus clearance but through different mechanisms. Mucolytics are often used in COPD, CF, and bronchiectasis. Guaifenesin is commonly found in OTC cough preparations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','flashcard','What is the adult dose of carbocisteine recommended in Ghana STG 2017 for acute bronchitis with productive cough?','["500-750 mg orally, 6-8 hourly"]','A','Carbocisteine is also given to children: 62.5-125 mg every 6 hours for ages 2-5 years. It is not recommended for children under 2 years. It alters the viscosity and structure of mucus glycoproteins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','flashcard','What special warning must be given to patients prescribed nebulised NAC?','["Nebulised NAC can trigger bronchospasm in patients with reactive airway disease (asthma, COPD); a SABA bronchodilator should be given first if the patient has reactive airways"]','A','NAC''''s sulfhydryl group can irritate the bronchial mucosa when inhaled. Oral NAC does not cause bronchospasm. If bronchospasm develops during nebulisation, stop immediately and administer a bronchodilator.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','flashcard','Why is dornase alfa (DNase) preferred over NAC as a mucolytic in cystic fibrosis?','["In CF, neutrophils release massive amounts of extracellular DNA into the airways, contributing substantially to sputum viscosity. Dornase alfa specifically cleaves this DNA, addressing a major component of CF mucus viscosity that NAC cannot target."]','A','NAC breaks mucin disulfide bonds but cannot address DNA-mediated viscosity. Dornase alfa is given by nebulisation once or twice daily and is CF-specific. It is too expensive for routine use in non-CF conditions.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','flashcard','Is guaifenesin an antitussive, a mucolytic, or an expectorant? What is the clinical implication?','["Guaifenesin is an EXPECTORANT (not an antitussive and not a mucolytic). It increases respiratory secretion volume to facilitate expectoration but does NOT suppress cough."]','A','Patients sometimes confuse guaifenesin-containing products with antitussives. Guaifenesin is appropriate for productive cough to help clear mucus. When combined with codeine or dextromethorphan in OTC products, the antitussive component suppresses the cough.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','flashcard','What are the mucolytic drugs listed in Ghana STG 2017 for management of productive cough in acute and chronic bronchitis?','["Carbocisteine (oral, for adults and children 2-5 years) is listed as a mucolytic for productive cough in both acute and chronic bronchitis in Ghana STG 2017"]','A','Ghana STG 2017 recommends carbocisteine for productive cough in acute bronchitis (500-750 mg 8-hourly in adults) and chronic bronchitis. This aligns with the availability and affordability of the drug in Ghana.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','hard','flashcard','How does carbocisteine reduce mucus viscosity at a molecular level, and how does this differ from NAC?','["Carbocisteine does NOT have a free sulfhydryl group and does NOT break disulfide bonds (unlike NAC). Instead, it alters the pattern of mucus glycoprotein biosynthesis in goblet cells, changing the ratio of sialomucins to fucomucins, resulting in less viscous mucus."]','A','This distinction is pharmacologically important: NAC = mucolytic by breaking disulfide bonds. Carbocisteine = mucoregulator by altering mucus glycoprotein structure. Both reduce sputum viscosity but by entirely different mechanisms.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','hard','flashcard','In what way does NAC provide antioxidant benefit in COPD beyond its mucolytic effect?','["NAC is a precursor of cysteine, which is a rate-limiting substrate for glutathione synthesis. By increasing intracellular glutathione, NAC reduces oxidative stress in alveolar cells and may reduce COPD exacerbation frequency independently of its mucolytic effect."]','A','Oxidative stress is central to COPD pathophysiology (from cigarette smoke and neutrophil-derived reactive oxygen species). NAC''''s antioxidant properties have been studied in COPD, with some evidence supporting reduction of exacerbations at high doses (600 mg twice daily).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','flashcard','What is the mechanism by which codeine suppresses cough?','["Codeine acts centrally as an opioid (mu-receptor agonist) on the cough centre in the medulla oblongata, reducing its sensitivity to peripheral stimuli and decreasing mucosal secretion"]','A','Antitussive effects occur at doses lower than analgesic doses. Common side effects include constipation, nausea, and sedation. Codeine has dependence potential and is contraindicated in patients with history of opioid use disorder.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','flashcard','How does benzonatate differ mechanistically from opioid antitussives?','["Benzonatate acts PERIPHERALLY \u2014 it anesthetises stretch receptors in the respiratory passages, lungs, and pleura, reducing the afferent limb of the cough reflex. It has NO central cough suppression and NO opioid activity."]','A','Benzonatate is a useful option when opioid antitussives are inappropriate (e.g., substance use disorder history). It has no analgesic effects and minimal abuse potential. Capsules must be swallowed intact to avoid oropharyngeal anaesthesia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','flashcard','At what dose does dextromethorphan have significant abuse potential, and what receptors are involved?','["At recommended antitussive doses, dextromethorphan has LOW abuse potential (acts on sigma receptors). At high (supratherapeutic) doses, it acts as an NMDA receptor antagonist, causing dissociative effects (robo-tripping)"]','A','Dextromethorphan is the active ingredient in many OTC cough products. Despite low abuse potential at therapeutic doses, it is misused at high doses for its dissociative effects. Prescribe with awareness in adolescent patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','flashcard','Which antitussive should be avoided in a patient on an MAO inhibitor, and why?','["Dextromethorphan \u2014 it inhibits serotonin reuptake and interacts with MAO inhibitors to cause serotonin syndrome (hyperthermia, agitation, clonus, diaphoresis, tremor)"]','A','This is a serious, potentially fatal drug interaction. Dextromethorphan is contraindicated with all MAO inhibitors (phenelzine, tranylcypromine, selegiline). Allow a washout period of 14 days after stopping an MAOI before using dextromethorphan.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','flashcard','What are the Ghana STG 2017 antitussive recommendations for dry cough in children under 4 years?','["Dextromethorphan is NOT recommended for children under 4 years. Codeine is also restricted in young children. For very young children, non-pharmacological approaches (fluids, humidified air) are preferred."]','A','Safety concerns about opioid antitussives in young children (risk of respiratory depression) and dextromethorphan in very young children (immature liver metabolism) have led to restrictions on their use in this age group globally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','flashcard','What is the preferred antitussive for a patient with a history of opioid addiction presenting with dry viral cough?','["Benzonatate \u2014 it is non-opioid, acts peripherally, has no abuse potential, and is equally effective for cough suppression without risk of triggering opioid relapse"]','A','Dextromethorphan may also be considered as it has low abuse potential at therapeutic doses, but benzonatate is the safer choice in patients with active opioid use disorder history. Codeine is absolutely contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','flashcard','A patient presents with persistent dry cough 6 weeks after starting ramipril for hypertension. What is the pharmacological basis, and what is the management?','["ACE inhibitors inhibit bradykinin degradation (kinin potentiation), causing accumulation of bradykinin and substance P in the airways, triggering cough via airway C-fibre stimulation. Management: switch to an angiotensin receptor blocker (ARB), which does not affect bradykinin."]','A','ACE inhibitor cough occurs in 10-15% of patients (higher in Asian populations and women). The cough is dry, persistent, and non-productive. It resolves within 1-4 weeks of stopping the ACE inhibitor. ARBs do not cause this side effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','flashcard','Why should productive cough from a lower respiratory tract infection NOT be suppressed with antitussives in most cases?','["Productive cough is a defence mechanism that helps clear infected secretions from the airways. Suppressing it with antitussives may impair bacterial clearance, prolong infection, and potentially cause sputum retention and worsening infection."]','A','The priority should always be to identify and treat the underlying cause of cough. Mucolytics or expectorants may be more appropriate for productive cough to facilitate clearance rather than suppress the protective cough reflex.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','hard','flashcard','What is the specific warning for benzonatate capsules, and what is the pharmacological mechanism of this risk?','["Benzonatate capsules must NOT be bitten, chewed, or sucked \u2014 if broken, the drug contacts oral mucosa directly, causing immediate oropharyngeal anaesthesia (numbness, choking sensation, laryngospasm) and potential cardiovascular effects (hypotension, arrhythmias) from rapid systemic absorption"]','A','Benzonatate is chemically related to tetracaine (a local anesthetic). When the capsule is intact, the drug is absorbed slowly from the GI tract. If broken, it rapidly anesthetises the oropharyngeal mucosa and can cause cardiovascular toxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','hard','flashcard','Dextromethorphan is a D-isomer of levorphanol. Why does it lack analgesic properties at antitussive doses despite being an opioid-related compound?','["The D-isomer (dextrorotatory) has negligible affinity for mu-opioid receptors (which mediate analgesia) but acts on sigma receptors and NMDA receptors. Analgesic opioids are L-isomers (levorotatory) with high mu-receptor affinity. Stereochemical chirality determines pharmacological activity."]','A','Stereochemical chirality is pharmacologically critical: L-levorphanol is a potent opioid analgesic, while D-dextromethorphan lacks mu-receptor affinity and thus has no analgesic effects at antitussive doses.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','flashcard','Name three drug classes used in pulmonary arterial hypertension (PAH) with an example of each.','["1. PDE5 inhibitors: sildenafil, tadalafil. 2. Endothelin receptor antagonists (ERAs): bosentan, ambrisentan, macitentan. 3. Prostacyclin analogues: epoprostenol, iloprost, treprostinil."]','A','These three classes target different pathways in PAH pathophysiology (NO-cGMP pathway, endothelin pathway, and prostacyclin pathway). Combination therapy targeting multiple pathways is often used in moderate-to-severe PAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','flashcard','Why must epoprostenol be administered by continuous IV infusion?','["Epoprostenol (prostacyclin) has an extremely short half-life of 3-5 minutes in the circulation and rapidly degrades at room temperature; continuous IV infusion via a central venous catheter is the only practical way to maintain therapeutic plasma levels"]','A','Abrupt interruption of epoprostenol infusion causes rebound severe pulmonary hypertension and can be fatal. Patients must have an indwelling central venous catheter and back-up supply of drug. Inhaled iloprost is an alternative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','flashcard','What is the mechanism of sildenafil in PAH?','["Sildenafil inhibits PDE5, the enzyme that degrades cGMP in pulmonary vascular smooth muscle, increasing cGMP levels and potentiating nitric oxide-mediated vasodilation, reducing pulmonary vascular resistance"]','A','Nitric oxide stimulates soluble guanylate cyclase to produce cGMP. Sildenafil prevents its breakdown. The net effect is prolonged vasodilation. Sildenafil is also approved for erectile dysfunction via the same mechanism in penile vasculature.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','flashcard','What is the teratogenicity risk of bosentan and what contraceptive counselling is required?','["Bosentan is teratogenic (causes major birth defects); additionally, bosentan induces CYP3A4 and 2C9, reducing the efficacy of hormonal contraceptives. Two reliable methods of contraception are mandatory; monthly pregnancy testing and liver function monitoring are required."]','A','Bosentan is only available through restricted programmes due to this risk. Liver function monitoring is required monthly as bosentan can cause dose-dependent hepatotoxicity. These dual monitoring requirements complicate its use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','flashcard','How does endothelin-1 contribute to PAH, and how do ERAs address this?','["Endothelin-1 (ET-1) is a potent vasoconstrictor and smooth muscle mitogen elevated in PAH, acting on ETA and ETB receptors in pulmonary vasculature, driving vasoconstriction and vascular remodelling. ERAs block these receptors, reducing pulmonary vascular resistance and inhibiting vascular remodelling."]','A','Bosentan blocks both ETA and ETB (dual antagonist); ambrisentan and macitentan are ETA-selective. The clinical significance of ETA vs. dual blockade on outcomes is debated but both approaches are effective in PAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','flashcard','Why is sildenafil absolutely contraindicated with nitrates?','["Both sildenafil (via PDE5 inhibition increasing cGMP) and nitrates (via NO release increasing cGMP) increase vascular cGMP levels; combining them causes additive vasodilation resulting in profound, potentially fatal hypotension"]','A','This interaction applies to all PDE5 inhibitors (sildenafil, tadalafil, vardenafil). It is one of the most important contraindications in pharmacology. Patients prescribed PDE5 inhibitors must not use any nitrate preparation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','flashcard','What is riociguat and how does it differ from sildenafil?','["Riociguat is a soluble guanylate cyclase (sGC) STIMULATOR \u2014 it directly activates sGC to produce more cGMP AND sensitises sGC to nitric oxide. Sildenafil is a PDE5 INHIBITOR \u2014 it prevents cGMP degradation. Both increase cGMP but at different points in the same pathway."]','A','Riociguat is also approved for chronic thromboembolic pulmonary hypertension (CTEPH). It is absolutely contraindicated with PDE5 inhibitors due to risk of additive severe hypotension.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','flashcard','What is the risk of abrupt epoprostenol discontinuation and how should it be managed?','["Abrupt cessation causes life-threatening rebound pulmonary hypertension (sudden loss of vasodilation) leading to acute right heart failure and death. Management: never abruptly stop; ensure emergency back-up pump and drug supply; if line is lost, use alternative vasodilators immediately while restarting infusion."]','A','Patient education is critical: patients must understand the danger of pump failure or line disconnection. Many patients wear a portable infusion pump 24 hours a day and carry emergency supplies wherever they go.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','hard','flashcard','Explain the pharmacokinetic interaction between bosentan and sildenafil when used together in PAH.','["Bosentan is a potent inducer of CYP3A4 (and CYP2C9). Sildenafil is primarily metabolised by CYP3A4. When co-administered, bosentan dramatically increases sildenafil''''s metabolism, reducing sildenafil AUC by approximately 63%, potentially reducing its therapeutic efficacy and requiring dose adjustment or monitoring of clinical response."]','A','This is a clinically relevant interaction in PAH combination therapy. The reverse interaction (sildenafil inhibiting bosentan metabolism) is less significant. Monitoring of clinical response to sildenafil when combined with bosentan is important.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','hard','flashcard','Describe the pharmacological differences between iloprost (inhaled) and epoprostenol (IV) as prostacyclin-based therapies for PAH.','["Both are prostacyclin analogues acting on IP receptors (increasing cAMP causing vasodilation and platelet inhibition). Epoprostenol = natural prostacyclin, t1/2 3-5 min, requires continuous IV infusion, most potent. Iloprost = stable synthetic analogue, t1/2 ~20-30 min, administered as inhaled nebulisation 6-9 times daily, avoids systemic hypotension but requires very frequent dosing."]','A','Treprostinil is another stable prostacyclin analogue available as IV, subcutaneous, and inhaled formulations, allowing greater flexibility. The short half-lives of prostanoids remain a key challenge requiring continuous or frequent administration.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','flashcard','Why are non-selective beta-blockers (e.g., propranolol) contraindicated in asthma?','["Non-selective beta-blockers block beta-2 receptors on bronchial smooth muscle, preventing physiological bronchodilation and causing bronchoconstriction. Even topical ophthalmic beta-blockers (e.g., timolol eye drops) can cause sufficient systemic absorption to precipitate asthma attacks."]','A','If a beta-blocker is essential for a patient with asthma (e.g., post-MI), a cardioselective beta-1 blocker (e.g., bisoprolol, atenolol) can be used with caution. Cardioselectivity is dose-dependent and not absolute.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','flashcard','What two measures prevent oropharyngeal candidiasis from ICS use?','["1. Rinse the mouth with water (swish-and-spit) after each inhaler use. 2. Use a spacer device (reduces drug deposition in the oropharynx)."]','A','Both measures significantly reduce the local immune suppression that leads to Candida overgrowth. If candidiasis occurs, treat with topical antifungals (nystatin, clotrimazole); rarely systemic azoles are needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','flashcard','Name three drugs that inhibit theophylline metabolism (CYP1A2/3A4), raising theophylline levels and risking toxicity.','["Macrolides (erythromycin, clarithromycin), fluoroquinolones (ciprofloxacin, norfloxacin), cimetidine, zileuton, fluvoxamine"]','A','Any of these can raise serum theophylline into the toxic range (>20 mcg/mL). Theophylline dose should be reduced (often halved) when these are co-prescribed, and serum levels monitored. The interaction with macrolides and ciprofloxacin is particularly clinically significant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','flashcard','What is aspirin-exacerbated respiratory disease (AERD) and which drug classes are contraindicated?','["AERD (Samter''''s triad) = asthma + chronic rhinosinusitis with nasal polyps + exacerbations triggered by aspirin/NSAIDs. All NSAIDs and aspirin are contraindicated. Management: avoidance of NSAIDs, LTRAs (montelukast), or zileuton; aspirin desensitisation in selected cases."]','A','AERD occurs in ~10% of asthmatics. The mechanism is COX-1 inhibition diverting arachidonic acid to the 5-lipoxygenase pathway, massively increasing cysteinyl leukotriene production. Paracetamol (acetaminophen) at low doses is generally safe.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','flashcard','What are the systemic adverse effects of long-term high-dose ICS use, particularly relevant in children?','["Growth retardation (reduced growth velocity), HPA axis suppression (risk of adrenal crisis with stress or surgery), reduced bone mineral density, cataracts, skin thinning"]','A','These effects are dose-dependent. Standard doses of ICS are relatively safe. In children, use the lowest effective dose and regularly review whether step-down is possible. Monitor growth velocity annually in children on ICS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','flashcard','A patient on ICS develops hoarseness (dysphonia). What is the cause and management?','["Hoarseness is caused by ICS deposition on the laryngeal mucosa, causing local steroid myopathy and possible candidiasis of the vocal cords. Management: ensure correct inhaler technique, use a spacer, reduce ICS dose to the minimum effective dose; rinse mouth thoroughly after use."]','A','Dysphonia affects approximately 30-50% of patients using high-dose ICS. It can be professionally limiting (e.g., singers, teachers). Unlike candidiasis, it does not respond to antifungals. Switching to a different ICS formulation may help.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','flashcard','Why does ICS use in COPD patients increase the risk of pneumonia, while this risk is not as prominent in asthma?','["In COPD, existing immune dysfunction predisposes to bacterial infection. ICS further suppress local pulmonary immunity in the lower airways, increasing susceptibility to pneumococcal pneumonia. In asthma, ICS reverse the disease-specific immune dysregulation, partially restoring immune function rather than impairing it."]','A','This is a key distinction explaining why ICS use in COPD is restricted (only for FEV1 <60% or overlap), while ICS are first-line in all persistent asthma. Fluticasone-containing ICS may have a higher pneumonia risk in COPD than budesonide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','flashcard','What is the mechanism and management of ICS-associated adrenal crisis in perioperative patients?','["High-dose long-term ICS suppress the HPA axis via systemic absorption. Under surgical stress, suppressed adrenal glands cannot produce adequate cortisol, causing adrenal crisis: hypotension, hypoglycaemia, hyponatraemia. Management: perioperative stress-dose corticosteroid cover with IV hydrocortisone."]','A','All patients on long-term high-dose ICS should be flagged for perioperative steroid cover. The threshold for this intervention is debated, but patients on ICS equivalent to >1.5 mg/kg/day prednisolone or with signs of HPA suppression are at highest risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','hard','flashcard','Explain the pharmacokinetic basis for the theophylline-ciprofloxacin interaction and the approximate dose adjustment required.','["Ciprofloxacin is a potent CYP1A2 inhibitor that can reduce theophylline clearance by approximately 30-50%. This means a patient on theophylline 300 mg twice daily may experience serum levels rising to toxic range; dose should typically be reduced by 30-50% with levels monitored within 48 hours of starting ciprofloxacin."]','A','The extent of inhibition varies by dose of ciprofloxacin and patient-specific factors. This is why individualised serum theophylline monitoring is essential rather than just empirical dose reduction. Norfloxacin causes a similar but less pronounced interaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','hard','flashcard','Beta-blockers are indicated post-MI and in heart failure. How should a clinician manage a patient who has both asthma and heart failure requiring beta-blockade?','["Use a cardioselective beta-1 blocker (bisoprolol, carvedilol, or metoprolol) at the lowest effective dose, with close monitoring for respiratory status; benefits of beta-blockade post-MI generally outweigh risks in mild-moderate asthma, but use is contraindicated in severe or brittle asthma"]','A','Cardioselectivity is imperfect and dose-dependent; even selective beta-1 blockers can cause bronchospasm in severe asthma. The cardiologist and respiratory physician should collaborate. Regular spirometry monitoring and SABA as rescue therapy are essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');